  color: var(--text-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 3.5rem); }
h2 { font-size: clamp(2rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.5rem, 3vw, 1.75rem); }
h4 { font-size: clamp(1.125rem, 2vw, 1.25rem); }

p {
  color: var(--text-secondary);
}

/* Layout */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.section {
  padding: var(--space-4xl) 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-md) var(--space-xl);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--duration-fast) var(--ease-out);
}

.btn-primary {
  background: var(--green-primary);
  color: white;
}

.btn-primary:hover {
  background: var(--green-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn-secondary:hover {
  background: var(--green-primary);
  color: white;
}

.btn-ghost {
  color: var(--green-primary);
  padding: var(--space-sm) var(--space-md);
}

.btn-ghost:hover {
  background: oklch(55% 0.22 145 / 0.1);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--surface-white);
  border-bottom: 1px solid var(--border-light);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--green-primary);
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--green-primary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 24px;
  height: 24px;
  fill: white;
}

.nav-main {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-links {
  display: flex;
  gap: var(--space-lg);
}

.nav-links a {
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--duration-fast);
}

.nav-links a:hover {
  color: var(--green-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.mobile-menu-btn {
  display: none;
  padding: var(--space-sm);
  color: var(--text-primary);
}

/* Hero */
.hero {
  background: linear-gradient(135deg, var(--cream-warm) 0%, var(--surface-white) 100%);
  padding: var(--space-4xl) 0;
  text-align: center;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  margin-bottom: var(--space-lg);
  color: var(--green-dark);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-xl);
}

/* Cards */
.card {
  background: var(--surface-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: transform var(--duration-normal) var(--ease-out), box-shadow var(--duration-normal) var(--ease-out);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.card-image {
  aspect-ratio: 4/3;
  background: var(--surface-cream);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.card-content {
  padding: var(--space-lg);
}

.card-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.card-text {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: var(--space-md);
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .grid-4, .grid-3, .grid-2 { grid-template-columns: 1fr; }
}

/* Section Headers */
.section-header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section-header h2 {
  margin-bottom: var(--space-md);
}

.section-header p {
  max-width: 600px;
  margin: 0 auto;
}

/* Footer */
.footer {
  background: var(--green-dark);
  color: white;
  padding: var(--space-4xl) 0 var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-3xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: oklch(80% 0.02 85);
  margin-top: var(--space-md);
  max-width: 280px;
}

.footer-col h4 {
  color: white;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-lg);
}

.footer-col ul li {
  margin-bottom: var(--space-sm);
}

.footer-col ul a {
  color: oklch(80% 0.02 85);
  font-size: 0.9375rem;
  transition: color var(--duration-fast);
}

.footer-col ul a:hover {
  color: white;
}

.footer-bottom {
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(50% 0.05 145);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  color: oklch(70% 0.02 85);
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }

  .footer-accordion {
    display: block;
  }

  .footer-accordion-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: var(--space-md) 0;
    color: white;
    font-weight: 600;
    font-size: 0.9375rem;
  }

  .footer-accordion-header svg {
    width: 20px;
    height: 20px;
    transition: transform var(--duration-normal);
  }

  .footer-accordion.active .footer-accordion-header svg {
    transform: rotate(180deg);
  }

  .footer-accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--duration-normal) var(--ease-out);
  }

  .footer-accordion.active .footer-accordion-content {
    max-height: 300px;
  }

  .footer-col-desktop {
    display: none;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--green-dark);
  color: white;
  padding: var(--space-lg);
  z-index: 200;
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
}

.cookie-content h4 {
  color: white;
  font-family: var(--font-body);
  margin-bottom: var(--space-xs);
}

.cookie-content p {
  color: oklch(80% 0.02 85);
  font-size: 0.875rem;
}

.cookie-actions {
  display: flex;
  gap: var(--space-md);
  flex-shrink: 0;
}

/* Carousel */
.carousel {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--space-sm);
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-item {
  flex: 0 0 calc(25% - var(--space-lg));
  scroll-snap-align: start;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--surface-white);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--duration-fast);
}

.carousel-btn:hover {
  background: var(--green-primary);
  color: white;
}

.carousel-btn.prev { left: -24px; }
.carousel-btn.next { right: -24px; }

.carousel-btn svg {
  width: 24px;
  height: 24px;
}

/* Tabs */
.tabs {
  display: flex;
  gap: var(--space-sm);
  border-bottom: 2px solid var(--border-light);
  margin-bottom: var(--space-xl);
  overflow-x: auto;
}

.tab {
  padding: var(--space-md) var(--space-lg);
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all var(--duration-fast);
  white-space: nowrap;
}

.tab:hover {
  color: var(--green-primary);
}

.tab.active {
  color: var(--green-primary);
  border-bottom-color: var(--green-primary);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Form Elements */
.input {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  font-size: 1rem;
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--surface-white);
  transition: all var(--duration-fast);
}

.input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.input-group {
  position: relative;
}

.input-icon {
  position: absolute;
  left: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}

/* Toggle */
.toggle-group {
  display: inline-flex;
  background: var(--surface-cream);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-full);
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--duration-fast);
}

.toggle-btn.active {
  background: var(--green-primary);
  color: white;
  box-shadow: var(--shadow-sm);
}

/* Mobile Menu */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--surface-white);
  z-index: 150;
  padding: var(--space-2xl);
}

.mobile-nav.open {
  display: flex;
  flex-direction: column;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.mobile-nav-links a {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
}

@media (max-width: 768px) {
  .nav-links, .nav-actions {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .hero {
    padding: var(--space-2xl) 0;
  }

  .section {
    padding: var(--space-2xl) 0;
  }
}

/* Utility Classes */
.text-center { text-align: center; }
.text-left { text-align: left; }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

