      const toggleBtns = document.querySelectorAll('.toggle-btn');
      const searchInput = document.querySelector('[data-store-search]');
      const storeCards = document.querySelectorAll('.store-card');
      const filterChips = document.querySelectorAll('.filter-chip');

      // Toggle filter panel
      if (filterBtn && filterPanel) {
        filterBtn.addEventListener('click', () => {
          filterPanel.classList.toggle('show');
          filterPanel.style.display = filterPanel.classList.contains('show') ? 'block' : 'none';
        });
      }

      // Toggle pickup/delivery
      toggleBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          toggleBtns.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
        });
      });

      // Filter chips toggle
      filterChips.forEach(chip => {
        chip.addEventListener('click', () => {
          chip.classList.toggle('active');
        });
      });

      // Store card selection
      storeCards.forEach(card => {
        card.addEventListener('click', () => {
          storeCards.forEach(c => c.classList.remove('selected'));
          card.classList.add('selected');
        });
      });

      // Search functionality
      if (searchInput) {
        let timeout;
        searchInput.addEventListener('input', () => {
          clearTimeout(timeout);
          timeout = setTimeout(() => {
            const query = searchInput.value.toLowerCase();
            storeCards.forEach(card => {
              const text = card.textContent.toLowerCase();
              card.style.display = text.includes(query) ? '' : 'none';
            });
          }, 300);
        });
      }
    });
  </script>
</body>
</html>
